//! 🧪️ Borrowed contexts retain the exact private Arc count while public admission laws live independently.
use super::*;
#[test]
fn original_payload_authority_private_borrow_does_not_clone_its_ledger(){
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let operation=OperationId(99203);let generation=Generation(7);let(cancel,root)=CancelToken::admit_root(grant).unwrap().unwrap();let(mut authority,birth)=JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap();let pointer=Arc::as_ptr(authority.original().unwrap());let count=Arc::strong_count(authority.original().unwrap());let mut sequence=0;
 for _ in 0..17{let mut receipt=Default::default();let cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();assert_eq!(Arc::as_ptr(&cx.payload_ledger),pointer);assert_eq!(Arc::strong_count(&cx.payload_ledger),count);drop(cx);assert_eq!(Arc::as_ptr(authority.original().unwrap()),pointer);assert_eq!(Arc::strong_count(authority.original().unwrap()),count);}
 let step=authority.close_step(grant).unwrap();assert_eq!(step.progress().released_bytes,birth.retained_capacity_bytes);let mut owner=semio_framework_async::CancelTokenRetirement::from_token(cancel);let mut released=0;for _ in 0..8{if owner.terminal_is_empty(){break}released+=owner.close_step(grant).unwrap().progress().released_bytes;}assert!(owner.terminal_is_empty());assert_eq!(released,root.retained_capacity_bytes);
}
